using System.Windows;using System.Windows.Controls;using Crown___Sovereign.Models;using Crown___Sovereign.Services;using Crown___Sovereign.Data;namespace Crown___Sovereign.Views.UserControls.Administracion.Sistema;public partial class ModulosParametrosControl:UserControl{private readonly AdministracionService _service=new();public ModulosParametrosControl(){InitializeComponent();Refresh();}private void Refresh()=>ModulesGrid.ItemsSource=SampleData.Modulos.Select(m=>new{Modulo=m,m.Nombre,m.Descripcion,Estado=m.Activo?"Activo":"Inactivo"}).ToList();private void Toggle_Click(object s,RoutedEventArgs e){if((s as FrameworkElement)?.DataContext is not object row)return;var item=(ModuloModel)row.GetType().GetProperty("Modulo")!.GetValue(row)!;_service.CambiarEstadoModulo(item.Id,!item.Activo);Refresh();}}
